remaining_goal:
f : ℝ → ℝ
a M0 M1 M2 : ℝ
hf' : DifferentiableOn ℝ f (Set.Ioi a)
hf'' : DifferentiableOn ℝ (deriv f) (Set.Ioi a)
hM0 : M0 = sSup {x | ∃ x_1 ∈ Set.Ioi a, |f x_1| = x}
hM1 : M1 = sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv f x_1| = x}
hM2 : M2 = sSup {x | ∃ x_1 ∈ Set.Ioi a, |deriv (deriv f) x_1| = x}
⊢ M1 ^ 2 ≤ 4 * M0 * M2
